WITH supplier_summary AS (SELECT supplier_id, MIN(launch_date) AS min_launch_date, ROUND(STDDEV(price), 2) AS stddev_price FROM products WHERE category IN ('Sports', 'Home') GROUP BY supplier_id) SELECT s.id, s.rating, s.supplier_name, ss.min_launch_date, ss.stddev_price FROM suppliers s INNER JOIN supplier_summary ss ON s.id = ss.supplier_id WHERE ss.stddev_price > 35 ORDER BY stddev_price DESC, id LIMIT 10
